using BARANG.Core.Application.Abstractions.Companies;
using BARANG.Core.Application.Abstractions.Transactions;
using BARANG.Core.Application.Auditing;
using BARANG.Core.Application.Pagination;
using BARANG.Core.Domain.Catalog;
using BARANG.Core.Domain.Common;
namespace BARANG.Core.Application.Catalog;

public sealed class CatalogAdministration(ICatalogStore store, IProductSalesPriceStore salesPrices, ITransactionExecutor tx, ICompanyContext company, IAuditWriter audit, TimeProvider time) : ICatalogAdministration
{
    public Task<Result<ProductView>> CreateProductAsync(ProductCommand c, CancellationToken ct) => tx.ExecuteAsync(async t => { Result<Product> x = Product.Create(Guid.NewGuid(), company.RequireCompanyId(), c.ProductCode, c.Name, c.Description, c.ProductTypeCode, c.UnitOfMeasureCode, time.GetUtcNow()); if (x.IsFailure) return Result.Failure<ProductView>(x.Error); if (await store.ProductCodeExistsAsync(x.Value.ProductCode, t)) return Result.Failure<ProductView>(CatalogErrors.DuplicateCode); store.Add(x.Value); Log(AuditActions.ProductCreated, "product", x.Value.Id, AuditChangeKind.Added); return Result.Success(P(x.Value)); }, ct); public Task<Result<ProductView>> GetProductAsync(Guid id, CancellationToken ct) => Read(async t => Map(await store.ProductAsync(id, t), P), ct); public Task<Result<PagedResult<ProductView>>> SearchProductsAsync(CatalogQuery q, CancellationToken ct) => Read(async t => Page(await store.SearchProductsAsync(q, t), P), ct); public Task<Result<IReadOnlyList<ProductOption>>> ProductOptionsAsync(string? s, int limit, CancellationToken ct) => Read(async t => limit is < 1 or > 100 ? Bad<IReadOnlyList<ProductOption>>() : Result.Success<IReadOnlyList<ProductOption>>((await store.ProductOptionsAsync(s, limit, t)).Select(x => new ProductOption(x.Id, x.ProductCode, x.Name)).ToArray()), ct); public Task<Result<ProductView>> UpdateProductAsync(Guid id, ProductCommand c, CancellationToken ct) => Change(id, c.Version, store.ProductAsync, (x) => x.Update(c.Name, c.Description, c.ProductTypeCode, c.UnitOfMeasureCode, time.GetUtcNow()), P, AuditActions.ProductUpdated, "product", ct); public Task<Result<ProductView>> SetProductActiveAsync(Guid id, bool active, long v, CancellationToken ct) => Change(id, v, store.ProductAsync, x => { x.SetActive(active, time.GetUtcNow()); return Result.Success(); }, P, active ? AuditActions.ProductActivated : AuditActions.ProductDeactivated, "product", ct);
    public Task<Result<VariantView>> CreateVariantAsync(Guid productId, VariantCommand c, CancellationToken ct) => tx.ExecuteAsync(async t => { Product? p = await store.ProductAsync(productId, t); if (p is null) return Result.Failure<VariantView>(CatalogErrors.NotFound); Result<ProductVariant> x = ProductVariant.Create(Guid.NewGuid(), p, c.Sku, c.DisplayName, c.Barcode, c.SizeCode, c.ColorCode, time.GetUtcNow()); if (x.IsFailure) return Result.Failure<VariantView>(x.Error); if (await store.SkuExistsAsync(x.Value.Sku, t) || x.Value.Barcode is not null && await store.BarcodeExistsAsync(x.Value.Barcode, t)) return Result.Failure<VariantView>(CatalogErrors.DuplicateCode); store.Add(x.Value); Log(AuditActions.ProductVariantCreated, "product_variant", x.Value.Id, AuditChangeKind.Added); return Result.Success(V(x.Value, p.IsActive)); }, ct); public Task<Result<IReadOnlyList<VariantView>>> ListVariantsAsync(Guid productId, bool activeOnly, CancellationToken ct) => Read(async t => { Product? p = await store.ProductAsync(productId, t); return p is null ? Result.Failure<IReadOnlyList<VariantView>>(CatalogErrors.NotFound) : Result.Success<IReadOnlyList<VariantView>>((await store.VariantsAsync(productId, activeOnly, t)).Select(x => V(x, p.IsActive)).ToArray()); }, ct); public Task<Result<IReadOnlyList<VariantOption>>> VariantOptionsAsync(Guid productId, string? search, int limit, CancellationToken ct) => Read(async t => { if (limit is < 1 or > 100) return Bad<IReadOnlyList<VariantOption>>(); Product? p = await store.ProductAsync(productId, t); if (p is null) return Result.Failure<IReadOnlyList<VariantOption>>(CatalogErrors.NotFound); if (!p.IsActive) return Result.Success<IReadOnlyList<VariantOption>>([]); IEnumerable<ProductVariant> q = (await store.VariantsAsync(productId, true, t)).Where(x => string.IsNullOrWhiteSpace(search) || x.Sku.Contains(search.Trim(), StringComparison.OrdinalIgnoreCase) || x.DisplayName?.Contains(search.Trim(), StringComparison.OrdinalIgnoreCase) == true).Take(limit); return Result.Success<IReadOnlyList<VariantOption>>(q.Select(x => new VariantOption(x.Id, x.ProductId, x.Sku, x.DisplayName ?? x.Sku, x.SizeCode, x.ColorCode)).ToArray()); }, ct); public Task<Result<VariantView>> UpdateVariantAsync(Guid id, VariantCommand c, CancellationToken ct) => tx.ExecuteAsync(async t => { ProductVariant? x = await store.VariantAsync(id, t); if (x is null) return Result.Failure<VariantView>(CatalogErrors.NotFound); if (x.Version != c.Version) return Result.Failure<VariantView>(CatalogErrors.Concurrency); Result r = x.Update(c.DisplayName, c.Barcode, c.SizeCode, c.ColorCode, time.GetUtcNow()); if (r.IsFailure) return Result.Failure<VariantView>(r.Error); if (x.Barcode is not null && await store.BarcodeExistsAsync(x.Barcode, t)) return Result.Failure<VariantView>(CatalogErrors.DuplicateCode); Product p = (await store.ProductAsync(x.ProductId, t))!; Log(AuditActions.ProductVariantUpdated, "product_variant", id, AuditChangeKind.Modified); return Result.Success(V(x, p.IsActive)); }, ct); public Task<Result<VariantView>> SetVariantActiveAsync(Guid id, bool active, long v, CancellationToken ct) => tx.ExecuteAsync(async t => { ProductVariant? x = await store.VariantAsync(id, t); if (x is null) return Result.Failure<VariantView>(CatalogErrors.NotFound); if (x.Version != v) return Result.Failure<VariantView>(CatalogErrors.Concurrency); x.SetActive(active, time.GetUtcNow()); Product p = (await store.ProductAsync(x.ProductId, t))!; Log(active ? AuditActions.ProductVariantActivated : AuditActions.ProductVariantDeactivated, "product_variant", id, AuditChangeKind.Modified); return Result.Success(V(x, p.IsActive)); }, ct);
    public Task<Result<SupplierView>> CreateSupplierAsync(SupplierCommand c, CancellationToken ct) => tx.ExecuteAsync(async t => { Result<Supplier> x = Supplier.Create(Guid.NewGuid(), company.RequireCompanyId(), c.SupplierCode, c.DisplayName, c.LegalName, c.RegistrationNo, c.TaxId, c.PrimaryEmail, c.PrimaryPhone, c.PrimaryMobile, c.Website, c.Notes, time.GetUtcNow()); if (x.IsFailure) return Result.Failure<SupplierView>(x.Error); if (await store.SupplierCodeExistsAsync(x.Value.SupplierCode, t)) return Result.Failure<SupplierView>(CatalogErrors.DuplicateCode); store.Add(x.Value); Log(AuditActions.SupplierCreated, "supplier", x.Value.Id, AuditChangeKind.Added); return Result.Success(S(x.Value)); }, ct); public Task<Result<SupplierView>> GetSupplierAsync(Guid id, CancellationToken ct) => Read(async t => Map(await store.SupplierAsync(id, t), S), ct); public Task<Result<PagedResult<SupplierView>>> SearchSuppliersAsync(CatalogQuery q, CancellationToken ct) => Read(async t => Page(await store.SearchSuppliersAsync(q, t), S), ct); public Task<Result<IReadOnlyList<SupplierOption>>> SupplierOptionsAsync(string? s, int limit, CancellationToken ct) => Read(async t => limit is < 1 or > 100 ? Bad<IReadOnlyList<SupplierOption>>() : Result.Success<IReadOnlyList<SupplierOption>>((await store.SupplierOptionsAsync(s, limit, t)).Select(x => new SupplierOption(x.Id, x.SupplierCode, x.DisplayName)).ToArray()), ct); public Task<Result<SupplierView>> UpdateSupplierAsync(Guid id, SupplierCommand c, CancellationToken ct) => Change(id, c.Version, store.SupplierAsync, x => x.Update(c.DisplayName, c.LegalName, c.RegistrationNo, c.TaxId, c.PrimaryEmail, c.PrimaryPhone, c.PrimaryMobile, c.Website, c.Notes, time.GetUtcNow()), S, AuditActions.SupplierUpdated, "supplier", ct); public Task<Result<SupplierView>> SetSupplierActiveAsync(Guid id, bool a, long v, CancellationToken ct) => Change(id, v, store.SupplierAsync, x => { if (x.IsBlocked && a) return Result.Failure(SupplierCoreErrors.Blocked); x.SetActive(a, time.GetUtcNow()); return Result.Success(); }, S, a ? AuditActions.SupplierActivated : AuditActions.SupplierDeactivated, "supplier", ct);
    public Task<Result<SupplierProductView>> CreateSupplierProductAsync(Guid supplierId, SupplierProductCommand c, CancellationToken ct) => tx.ExecuteAsync(async t => { Supplier? s = await store.SupplierAsync(supplierId, t); Product? p = await store.ProductAsync(c.ProductId, t); ProductVariant? v = c.ProductVariantId is null ? null : await store.VariantAsync(c.ProductVariantId.Value, t); if (s is null || p is null || c.ProductVariantId is not null && (v is null || v.ProductId != p.Id)) return Result.Failure<SupplierProductView>(CatalogErrors.CrossCompanyReference); if (await store.SupplierProductExistsAsync(supplierId, p.Id, c.ProductVariantId, t)) return Result.Failure<SupplierProductView>(CatalogErrors.DuplicateRelationship); Result<SupplierProduct> x = SupplierProduct.Create(Guid.NewGuid(), company.RequireCompanyId(), supplierId, p.Id, c.ProductVariantId, c.SupplierItemCode, c.IsPreferred, c.MinimumOrderQuantity, c.LeadTimeDays, time.GetUtcNow()); if (x.IsFailure) return Result.Failure<SupplierProductView>(x.Error); await Preferred(x.Value, t); store.Add(x.Value); Log(AuditActions.SupplierProductCreated, "supplier_product", x.Value.Id, AuditChangeKind.Added); return Result.Success(SP(x.Value)); }, ct); public Task<Result<IReadOnlyList<SupplierProductView>>> ListSupplierProductsAsync(Guid id, bool active, CancellationToken ct) => Read(async t => await store.SupplierAsync(id, t) is null ? Result.Failure<IReadOnlyList<SupplierProductView>>(CatalogErrors.NotFound) : Result.Success<IReadOnlyList<SupplierProductView>>((await store.SupplierProductsAsync(id, active, t)).Select(SP).ToArray()), ct); public Task<Result<SupplierProductView>> UpdateSupplierProductAsync(Guid sid, Guid id, SupplierProductCommand c, CancellationToken ct) => ChangeRel(sid, id, c.Version, x => x.Update(c.SupplierItemCode, c.IsPreferred, c.MinimumOrderQuantity, c.LeadTimeDays, time.GetUtcNow()), AuditActions.SupplierProductUpdated, ct); public Task<Result<SupplierProductView>> SetSupplierProductActiveAsync(Guid sid, Guid id, bool a, long v, CancellationToken ct) => ChangeRel(sid, id, v, x => { x.SetActive(a, time.GetUtcNow()); return Result.Success(); }, a ? AuditActions.SupplierProductActivated : AuditActions.SupplierProductDeactivated, ct);
    public Task<Result<EquipmentView>> CreateEquipmentAsync(EquipmentCommand c, CancellationToken ct) => tx.ExecuteAsync(async t => { if (!await Location(c.BranchId, c.OrganizationalUnitId, t)) return Result.Failure<EquipmentView>(CatalogErrors.CrossCompanyReference); Result<Equipment> x = Equipment.Create(Guid.NewGuid(), company.RequireCompanyId(), c.EquipmentCode, c.Name, c.EquipmentTypeCode, c.OperationalStatusCode, c.BranchId, c.OrganizationalUnitId, c.Description, c.Manufacturer, c.Model, c.SerialNumber, time.GetUtcNow()); if (x.IsFailure) return Result.Failure<EquipmentView>(x.Error); if (await store.EquipmentCodeExistsAsync(x.Value.EquipmentCode, t)) return Result.Failure<EquipmentView>(CatalogErrors.DuplicateCode); store.Add(x.Value); Log(AuditActions.EquipmentCreated, "equipment", x.Value.Id, AuditChangeKind.Added); return Result.Success(E(x.Value)); }, ct); public Task<Result<EquipmentView>> GetEquipmentAsync(Guid id, CancellationToken ct) => Read(async t => Map(await store.EquipmentAsync(id, t), E), ct); public Task<Result<PagedResult<EquipmentView>>> SearchEquipmentAsync(CatalogQuery q, CancellationToken ct) => Read(async t => Page(await store.SearchEquipmentAsync(q, t), E), ct); public Task<Result<IReadOnlyList<EquipmentOption>>> EquipmentOptionsAsync(string? s, string? t, string? st, Guid? b, int limit, CancellationToken ct) => Read(async token => limit is < 1 or > 100 ? Bad<IReadOnlyList<EquipmentOption>>() : Result.Success<IReadOnlyList<EquipmentOption>>((await store.EquipmentOptionsAsync(s, t, st, b, limit, token)).Select(x => new EquipmentOption(x.Id, x.EquipmentCode, x.Name, x.EquipmentTypeCode, x.OperationalStatusCode)).ToArray()), ct); public Task<Result<EquipmentView>> UpdateEquipmentAsync(Guid id, EquipmentCommand c, CancellationToken ct) => tx.ExecuteAsync(async t => { Equipment? x = await store.EquipmentAsync(id, t); if (x is null) return Result.Failure<EquipmentView>(CatalogErrors.NotFound); if (x.Version != c.Version) return Result.Failure<EquipmentView>(CatalogErrors.Concurrency); if (!await Location(c.BranchId, c.OrganizationalUnitId, t)) return Result.Failure<EquipmentView>(CatalogErrors.CrossCompanyReference); string old = x.OperationalStatusCode; Result r = x.Update(c.Name, c.EquipmentTypeCode, c.OperationalStatusCode, c.BranchId, c.OrganizationalUnitId, c.Description, c.Manufacturer, c.Model, c.SerialNumber, time.GetUtcNow()); if (r.IsFailure) return Result.Failure<EquipmentView>(r.Error); Log(old == x.OperationalStatusCode ? AuditActions.EquipmentUpdated : AuditActions.EquipmentStatusChanged, "equipment", id, AuditChangeKind.Modified); return Result.Success(E(x)); }, ct); public Task<Result<EquipmentView>> SetEquipmentActiveAsync(Guid id, bool a, long v, CancellationToken ct) => Change(id, v, store.EquipmentAsync, x => { x.SetActive(a, time.GetUtcNow()); return Result.Success(); }, E, a ? AuditActions.EquipmentActivated : AuditActions.EquipmentDeactivated, "equipment", ct);
    public Task<Result<ProductSalesPriceView>> CreateProductSalesPriceAsync(Guid productId, ProductSalesPriceCommand c, CancellationToken ct) => tx.ExecuteAsync(async t => { Product? product = await store.ProductAsync(productId, t); ProductVariant? variant = c.ProductVariantId is null ? null : await store.VariantAsync(c.ProductVariantId.Value, t); if (product is null || variant is not null && variant.ProductId != productId) return Result.Failure<ProductSalesPriceView>(CatalogErrors.CrossCompanyReference); if (await salesPrices.OverlapsAsync(productId, c.ProductVariantId, c.StartDate, c.EndDate, null, t)) return Result.Failure<ProductSalesPriceView>(CatalogErrors.DuplicateRelationship); Result<ProductSalesPrice> created = ProductSalesPrice.Create(Guid.NewGuid(), company.RequireCompanyId(), productId, c.ProductVariantId, c.Amount, c.CurrencyCode, c.StartDate, c.EndDate, time.GetUtcNow()); if (created.IsFailure) return Result.Failure<ProductSalesPriceView>(created.Error); salesPrices.Add(created.Value); Log("product.sales_price.created", "product_sales_price", created.Value.Id, AuditChangeKind.Added); return Result.Success(Price(created.Value)); }, ct);
    public Task<Result<IReadOnlyList<ProductSalesPriceView>>> ListProductSalesPricesAsync(Guid productId, bool includeInactive, CancellationToken ct) => Read(async t => await store.ProductAsync(productId, t) is null ? Result.Failure<IReadOnlyList<ProductSalesPriceView>>(CatalogErrors.NotFound) : Result.Success<IReadOnlyList<ProductSalesPriceView>>((await salesPrices.ListAsync(productId, includeInactive, t)).Select(Price).ToArray()), ct);
    public Task<Result<ProductSalesPriceView>> GetProductSalesPriceAsync(Guid id, CancellationToken ct) => Read(async t => { ProductSalesPrice? x = await salesPrices.GetAsync(id, t); return x is null ? Result.Failure<ProductSalesPriceView>(CatalogErrors.NotFound) : Result.Success(Price(x)); }, ct);
    public Task<Result<ProductSalesPriceView>> UpdateProductSalesPriceAsync(Guid id, ProductSalesPriceCommand c, CancellationToken ct) => tx.ExecuteAsync(async t => { ProductSalesPrice? x = await salesPrices.GetAsync(id, t); if (x is null) return Result.Failure<ProductSalesPriceView>(CatalogErrors.NotFound); if (await salesPrices.OverlapsAsync(x.ProductId, x.ProductVariantId, c.StartDate, c.EndDate, id, t)) return Result.Failure<ProductSalesPriceView>(CatalogErrors.DuplicateRelationship); Result r = x.Update(c.Amount, c.CurrencyCode, c.StartDate, c.EndDate, c.Version, time.GetUtcNow()); if (r.IsFailure) return Result.Failure<ProductSalesPriceView>(r.Error); Log("product.sales_price.updated", "product_sales_price", id, AuditChangeKind.Modified); return Result.Success(Price(x)); }, ct);
    public Task<Result<ProductSalesPriceView>> SetProductSalesPriceActiveAsync(Guid id, bool active, long version, CancellationToken ct) => tx.ExecuteAsync(async t => { ProductSalesPrice? x = await salesPrices.GetAsync(id, t); if (x is null) return Result.Failure<ProductSalesPriceView>(CatalogErrors.NotFound); if (x.Version != version) return Result.Failure<ProductSalesPriceView>(CatalogErrors.Concurrency); if (active && await salesPrices.OverlapsAsync(x.ProductId, x.ProductVariantId, x.StartDate, x.EndDate, id, t)) return Result.Failure<ProductSalesPriceView>(CatalogErrors.DuplicateRelationship); x.SetActive(active, time.GetUtcNow()); Log(active ? "product.sales_price.activated" : "product.sales_price.deactivated", "product_sales_price", id, AuditChangeKind.Modified); return Result.Success(Price(x)); }, ct);
    public Task<Result> DeleteProductSalesPriceAsync(Guid id, long version, CancellationToken ct) => tx.ExecuteAsync(async t => { ProductSalesPrice? x = await salesPrices.GetAsync(id, t); if (x is null) return Result.Failure(CatalogErrors.NotFound); if (x.Version != version) return Result.Failure(CatalogErrors.Concurrency); if (x.MigratedFromTariffId is not null) return Result.Failure(Error.BusinessRule("catalog.product_sales_price_protected")); salesPrices.Remove(x); Log("product.sales_price.deleted", "product_sales_price", id, AuditChangeKind.Removed); return Result.Success(); }, ct);
    private Task<Result<TV>> Change<TE, TV>(Guid id, long v, Func<Guid, CancellationToken, Task<TE?>> find, Func<TE, Result> change, Func<TE, TV> view, string action, string entity, CancellationToken ct) where TE : CatalogEntity => tx.ExecuteAsync(async t => { company.RequireCompanyId(); TE? x = await find(id, t); if (x is null) return Result.Failure<TV>(CatalogErrors.NotFound); if (x.Version != v) return Result.Failure<TV>(CatalogErrors.Concurrency); Result r = change(x); if (r.IsFailure) return Result.Failure<TV>(r.Error); Log(action, entity, id, AuditChangeKind.Modified); return Result.Success(view(x)); }, ct);
    private Task<Result<SupplierProductView>> ChangeRel(Guid sid, Guid id, long v, Func<SupplierProduct, Result> change, string action, CancellationToken ct) => tx.ExecuteAsync(async t => { company.RequireCompanyId(); SupplierProduct? x = await store.SupplierProductAsync(sid, id, t); if (x is null) return Result.Failure<SupplierProductView>(CatalogErrors.NotFound); if (x.Version != v) return Result.Failure<SupplierProductView>(CatalogErrors.Concurrency); Result r = change(x); if (r.IsFailure) return Result.Failure<SupplierProductView>(r.Error); await Preferred(x, t); Log(action, "supplier_product", id, AuditChangeKind.Modified); return Result.Success(SP(x)); }, ct);
    private async Task<bool> Location(Guid? b, Guid? u, CancellationToken ct) => (b is null || await store.BranchExistsAsync(b.Value, ct)) && (u is null || await store.UnitExistsAsync(u.Value, ct));
    private Task<Result<T>> Read<T>(Func<CancellationToken, Task<Result<T>>> op, CancellationToken ct) { company.RequireCompanyId(); return tx.ExecuteAsync(op, ct); }
    private async Task Preferred(SupplierProduct relationship,CancellationToken ct) { foreach(var previous in await store.ReplacePreferredSupplierProductAsync(relationship,time.GetUtcNow(),ct)) Log("supplier.sourcing.preferred.cleared","supplier_product",previous.Id,AuditChangeKind.Modified); }
    private void Log(string a, string e, Guid id, AuditChangeKind k) => audit.Write(new(a, e, id.ToString(), CompanyId: company.RequireCompanyId(), ChangeKind: k)); private static Result<T> Bad<T>() => Result.Failure<T>(Error.Validation("catalog.invalid_pagination")); private static Result<TV> Map<TE, TV>(TE? x, Func<TE, TV> f) where TE : class => x is null ? Result.Failure<TV>(CatalogErrors.NotFound) : Result.Success(f(x)); private static Result<PagedResult<TV>> Page<TE, TV>(PagedResult<TE> x, Func<TE, TV> f) => Result.Success(new PagedResult<TV>(x.Items.Select(f), x.PageNumber, x.PageSize, x.TotalCount));
    private static ProductView P(Product x) => new(x.Id, x.ProductCode, x.Name, x.Description, x.ProductTypeCode, x.UnitOfMeasureCode, x.IsActive, x.Version); private static VariantView V(ProductVariant x, bool parent) => new(x.Id, x.ProductId, x.Sku, x.DisplayName, x.Barcode, x.SizeCode, x.ColorCode, x.IsActive, x.IsActive && parent, x.Version); private static ProductSalesPriceView Price(ProductSalesPrice x) => new(x.Id, x.ProductId, x.ProductVariantId, x.Amount, x.CurrencyCode, x.StartDate, x.EndDate, x.IsActive, x.Version, x.MigratedFromTariffId); private static SupplierView S(Supplier x) => new(x.Id, x.SupplierCode, x.DisplayName, x.LegalName, x.RegistrationNo, x.TaxId, x.PrimaryEmail, x.PrimaryPhone, x.PrimaryMobile, x.Website, x.Notes, x.IsActive, x.Version); private static SupplierProductView SP(SupplierProduct x) => new(x.Id, x.SupplierId, x.ProductId, x.ProductVariantId, x.SupplierItemCode, x.IsPreferred, x.MinimumOrderQuantity, x.LeadTimeDays, x.IsActive, x.Version); private static EquipmentView E(Equipment x) => new(x.Id, x.EquipmentCode, x.Name, x.EquipmentTypeCode, x.OperationalStatusCode, x.BranchId, x.OrganizationalUnitId, x.Description, x.Manufacturer, x.Model, x.SerialNumber, x.IsActive, x.Version);
    public Task<Result> DeleteProductAsync(Guid id, long version, CancellationToken ct) => tx.ExecuteAsync(async t => { Product? x = await store.ProductAsync(id, t); if (x is null) return Result.Failure(CatalogErrors.NotFound); if (x.Version != version) return Result.Failure(CatalogErrors.Concurrency); if (await store.ProductHasDependenciesAsync(id, t)) return Result.Failure(Error.BusinessRule("catalog.product_protected_dependency")); store.Remove(x); Log("product.deleted", "product", id, AuditChangeKind.Removed); return Result.Success(); }, ct);
    public Task<Result> DeleteVariantAsync(Guid id, long version, CancellationToken ct) => tx.ExecuteAsync(async t => { ProductVariant? x = await store.VariantAsync(id, t); if (x is null) return Result.Failure(CatalogErrors.NotFound); if (x.Version != version) return Result.Failure(CatalogErrors.Concurrency); if (await store.VariantHasDependenciesAsync(id, t)) return Result.Failure(Error.BusinessRule("catalog.variant_protected_dependency")); store.Remove(x); Log("product.variant.deleted", "product_variant", id, AuditChangeKind.Removed); return Result.Success(); }, ct);
}
